{v:'VER',what:'probe of the top centre text boxes',
 run:function(){
   if(!window.__deploy||!window.__endRaid||typeof __loop!=='function'||typeof __forceSize!=='function') return 'SKIP: no raid here';
   var out=[], rf=ctx.fillText, own=false, rec=[];
   function startRec(){ rec=[]; own=true; ctx.fillText=function(s,x,y){ var m=/([\d.]+)px/.exec(String(ctx.font||'')), px=m?+m[1]:12, w=0, t=null, al=ctx.textAlign;
       var asc=0.78*px, dsc=0.22*px;
       try{ var tm=ctx.measureText(String(s)); w=tm.width; if(isFinite(tm.actualBoundingBoxAscent)){ asc=tm.actualBoundingBoxAscent; dsc=tm.actualBoundingBoxDescent; } }catch(_e){} try{ t=ctx.getTransform(); }catch(_t){}
       var a=t?t.a:1, d=t?t.d:1, e=t?t.e:0, f=t?t.f:0, x0=x, x1=x+w;
       if(al==='center'){ x0=x-w/2; x1=x+w/2; } else if(al==='right'||al==='end'){ x0=x-w; x1=x; }
       rec.push({s:String(s),x0:a*x0+e,x1:a*x1+e,y0:d*(y-asc)+f,y1:d*(y+dsc)+f});
       return rf.apply(this,arguments); }; }
   function stopRec(){ if(own){ delete ctx.fillText; if(ctx.fillText!==rf) ctx.fillText=rf; own=false; } }
   function boxes(W2,H2){
     var keep=rec.filter(function(r){ return r.y0<H2*0.36&&r.x1>W2*0.30&&r.x0<W2*0.70&&r.s.trim().length>0; }), res=[], i, j, a, b;
     keep.sort(function(p,q){ return p.y0-q.y0; });
     var seen={}; keep=keep.filter(function(r){ var k=r.s+Math.round(r.y0); if(seen[k]) return false; seen[k]=1; return true; });
     var list=keep.map(function(r){ return Math.round(r.y0)+'-'+Math.round(r.y1); });
     for(i=0;i<keep.length;i++) for(j=i+1;j<keep.length;j++){ a=keep[i]; b=keep[j]; if(a.x0<b.x1-1&&b.x0<a.x1-1&&a.y0<b.y1-1&&b.y0<a.y1-1) res.push(a.s.slice(0,6)+'X'+b.s.slice(0,6)); }
     return {list:list.join(','),hit:res.join(' ')};
   }
   function frames(n,last){ for(var f=0;f<n;f++){ if(f===n-1&&last) startRec(); __loop(performance.now()+f*16.7); } stopRec(); }
   function stage(mode,state,Wd,Hd){
     var g, p, e, tag=mode+' '+state+' '+Wd+': ';
     __topClear(); __runPrep(); __resetCfg(); __pinDefaults(0); __forceSize(Wd,Hd);
     if(mode==='demo'){ if(typeof arcadeDeploy!=='function'||!arcadeDeploy({mapIx:0,seed:4242})) return tag+'no demo raid'; }
     else { __deploy({kit:[],safe:null,mapIx:0,seed:4242}); if(typeof careerPostBuild==='function'){ careerPostBuild(__state()); __state().cs.s=4200; __state().cs.k=17; } }
     g=__state(); if(!g||g.over) return tag+'no raid'; p=g.player; p.iv=99; g.ents.length=0;
     try{ if(g.arcade&&typeof ARCADE==='object'){ ARCADE.holdT=0; ARCADE.banner=null; g.shield=0; p.shield=0; } }catch(_a){}
     if(state==='alert'){ say('PILLAGER SPOTTED','warn',{sub:'NORTH WEST OF YOU'}); }
     else if(state==='loc'){ g.loc={m:'THE COLD MILE',T:5,at:(g.t||0)-1}; }
     else if(state==='wave'){ say('WAVE 3','warn'); }
     say('RADIO CHECK','info'); say('2 MINUTES LEFT','obj',{sub:'GET TO AN EXTRACTION'});
     if(typeof mkWarden==='function'&&typeof BOSS_NAME!=='undefined'){ e=mkWarden(p.x+240,p.y); e.boss=1; e.name=BOSS_NAME; e.r=44; e.barSeen=1; e.hp=e.maxhp||300; g.ents.push(e); g.bossRef=e; }
     frames(10,true);
     var r=boxes(Wd,Hd); out.push(mode.charAt(0)+state.charAt(0)+(Wd>2000?'4k':'hd')+(r.hit?(' HIT '+r.hit):' ok')+' '+r.list);
     try{ if(g.arcade&&typeof arcadeLeave==='function') arcadeLeave(); }catch(_l){}
     try{ if(__state()&&!__state().over) __endRaid('abandon'); }catch(_e){}
     return null;
   }
   try{
     [[1920,1080],[3840,2160]].forEach(function(SZ){ ['career','demo'].forEach(function(mode){ ['alert'].forEach(function(st){ var m=stage(mode,st,SZ[0],SZ[1]); if(m) out.push(m); }); }); });
   }catch(e){ out.push('threw: '+(e&&e.message||e)); }
   finally{ stopRec(); try{ __forceSize(1920,1080); }catch(_f){} try{ if(typeof arcadeLeave==='function'&&typeof ARCADE==='object'&&ARCADE&&ARCADE.on) arcadeLeave(); }catch(_a2){} try{ if(__state()&&!__state().over) __endRaid('abandon'); }catch(_e2){} __topClear(); }
   return 'PROBE '+out.join(' # '); }},
